// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;

    function setUp() public { c = new RoundFactory(); }

    function testFuzz_property(address potentialOwner, address newImpl) public {
        vm.assume(newImpl != address(0));

        vm.prank(potentialOwner);
        c.initialize();

        bool ok;
        vm.prank(potentialOwner);
        try c.updateRoundImplementation(payable(newImpl)) {
            ok = true;
        } catch {
            ok = false;
        }

        if (c.owner() == potentialOwner) {
            assertTrue(ok && c.roundImplementation() == newImpl);
        } else {
            assertTrue(c.owner() == c.owner());
        }
    }
}
